1	package dsl
2	
3	import (
4		"gopkg.in/yaml.v2"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
7	)
8	
9	func (c *Compiler) compileRoutes() {
10		for _, r := range c.prog.Routes {
11			c.config.Decisions = append(c.config.Decisions, c.compileRoute(r))
12		}
13	}
14	
15	func (c *Compiler) compileRoute(r *RouteDecl) config.Decision {
16		decision := config.Decision{
17			Name:        r.Name,
18			Description: r.Description,
19			Priority:    r.Priority,
20			Tier:        r.Tier,
21			Rules:       c.compileRouteRules(r),
22		}
23	
24		for _, m := range r.Models {
25			c.appendModelRef(&decision, m)
26		}
27	
28		for _, iter := range r.CandidateIterations {
29			compiled := c.compileCandidateIteration(iter)
30			decision.CandidateIterations = append(decision.CandidateIterations, compiled)
31			if compiled.Source == "models" && iterEmitsVariable(compiled) {
32				for _, model := range iter.Models {
33					c.appendModelRefIfMissing(&decision, model)
34				}
35			}
36		}
37	
38		if r.Algorithm != nil {
39			decision.Algorithm = c.compileAlgorithm(r.Algorithm)
40		}
41	
42		for _, pr := range r.Plugins {
43			if dp := c.compilePluginRef(pr); dp != nil {
44				decision.Plugins = append(decision.Plugins, *dp)
45			}
46		}
47	
48		c.compileRouteEmits(r, &decision)
49		return decision
50	}
51	
52	func (c *Compiler) compileRouteRules(r *RouteDecl) config.RuleCombination {
53		if r.When == nil {
54			return config.RuleCombination{Operator: "AND", Conditions: []config.RuleNode{}}
55		}
56		rules := c.compileBoolExpr(r.When)
57		if rules.Operator == "" && rules.Type != "" {
58			return config.RuleCombination{
59				Operator:   "AND",
60				Conditions: []config.RuleNode{rules},
61			}
62		}
63		return rules
64	}
65	
66	func (c *Compiler) compileRouteEmits(r *RouteDecl, decision *config.Decision) {
67		seenEmitKinds := make(map[string]bool, len(r.Emits))
68		for _, e := range r.Emits {
69			if e == nil {
70				continue
71			}
72			if seenEmitKinds[e.Kind] {
73				c.addError(e.Pos, "ROUTE %s EMIT: duplicate EMIT kind %q in the same route. Each kind may appear at most once", r.Name, e.Kind)
74				continue
75			}
76			seenEmitKinds[e.Kind] = true
77			if !c.validateEmitForCompile(r, e) {
78				continue
79			}
80			decision.Emits = append(decision.Emits, compileEmitDecl(e))
81		}
82	}
83	
84	func (c *Compiler) appendModelRef(decision *config.Decision, m *ModelRef) {
85		if decision == nil || m == nil {
86			return
87		}
88		ref := config.ModelRef{
89			Model:    m.Model,
90			LoRAName: m.LoRA,
91			Weight:   m.Weight,
92		}
93		if m.Reasoning != nil {
94			ref.UseReasoning = m.Reasoning
95		}
96		if m.Effort != "" {
97			ref.ReasoningEffort = m.Effort
98		}
99		decision.ModelRefs = append(decision.ModelRefs, ref)
100	
101		// Populate model_config for route-local model metadata fields.
102		if m.ParamSize != "" {
103			if c.config.ModelConfig == nil {
104				c.config.ModelConfig = make(map[string]config.ModelParams)
105			}
106			mc := c.config.ModelConfig[m.Model]
107			mc.ParamSize = m.ParamSize
108			c.config.ModelConfig[m.Model] = mc
109		}
110	}
111	
112	func (c *Compiler) appendModelRefIfMissing(decision *config.Decision, m *ModelRef) {
113		if decision == nil || m == nil {
114			return
115		}
116		for _, existing := range decision.ModelRefs {
117			if existing.Model == m.Model && existing.LoRAName == m.LoRA {
118				return
119			}
120		}
121		c.appendModelRef(decision, m)
122	}
123	
124	func (c *Compiler) compileCandidateIteration(iter *CandidateIterationDecl) config.CandidateIterationConfig {
125		if iter == nil {
126			return config.CandidateIterationConfig{}
127		}
128		compiled := config.CandidateIterationConfig{
129			Variable: iter.Variable,
130			Source:   iter.Source,
131		}
132		for _, model := range iter.Models {
133			ref := config.ModelRef{
134				Model:    model.Model,
135				LoRAName: model.LoRA,
136				Weight:   model.Weight,
137			}
138			if model.Reasoning != nil {
139				ref.UseReasoning = model.Reasoning
140			}
141			if model.Effort != "" {
142				ref.ReasoningEffort = model.Effort
143			}
144			compiled.Models = append(compiled.Models, ref)
145		}
146		for _, output := range iter.Outputs {
147			compiled.Outputs = append(compiled.Outputs, config.CandidateIterationOutputConfig{
148				Type:  output.Type,
149				Value: output.Value,
150			})
151		}
152		return compiled
153	}
154	
155	func (c *Compiler) compileBoolExpr(expr BoolExpr) config.RuleCombination {
156		switch e := expr.(type) {
157		case *BoolAnd:
158			// Flatten nested ANDs: (a AND b) AND c → AND(a, b, c)
159			conditions := c.flattenBoolExpr(expr, func(ex BoolExpr) bool {
160				_, ok := ex.(*BoolAnd)
161				return ok
162			}, func(ex BoolExpr) (BoolExpr, BoolExpr) {
163				a := ex.(*BoolAnd)
164				return a.Left, a.Right
165			})
166			return config.RuleCombination{
167				Operator:   "AND",
168				Conditions: conditions,
169			}
170		case *BoolOr:
171			// Flatten nested ORs: (a OR b) OR c → OR(a, b, c)
172			conditions := c.flattenBoolExpr(expr, func(ex BoolExpr) bool {
173				_, ok := ex.(*BoolOr)
174				return ok
175			}, func(ex BoolExpr) (BoolExpr, BoolExpr) {
176				o := ex.(*BoolOr)
177				return o.Left, o.Right
178			})
179			return config.RuleCombination{
180				Operator:   "OR",
181				Conditions: conditions,
182			}
183		case *BoolNot:
184			return config.RuleCombination{
185				Operator: "NOT",
186				Conditions: []config.RuleNode{
187					c.compileBoolExpr(e.Expr),
188				},
189			}
190		case *SignalRefExpr:
191			return c.compileSignalRefExpr(e)
192		default:
193			c.addError(Position{}, "unknown bool expression type %T", expr)
194			return config.RuleCombination{}
195		}
196	}
197	
198	func (c *Compiler) compileSignalRefExpr(
199		expr *SignalRefExpr,
200	) config.RuleCombination {
201		node := config.RuleCombination{
202			Type: expr.SignalType,
203			Name: expr.SignalName,
204		}
205		if label, ok := getStringField(expr.Fields, "label"); ok {
206			node.Label = label
207		}
208		if onError, ok := getStringField(expr.Fields, "on_error"); ok {
209			node.OnError = onError
210		}
211		if rawPredicate, ok := expr.Fields["predicate"].(ObjectValue); ok {
212			payload, err := yaml.Marshal(fieldsToMap(rawPredicate.Fields))
213			if err != nil {
214				c.addError(expr.Pos, "failed to encode predicate: %v", err)
215				return node
216			}
217			var predicate config.NumericPredicate
218			if err := yaml.Unmarshal(payload, &predicate); err != nil {
219				c.addError(expr.Pos, "failed to decode predicate: %v", err)
220				return node
221			}
222			node.Predicate = &predicate
223		}
224		return node
225	}
226	
227	func (c *Compiler) flattenBoolExpr(
228		expr BoolExpr,
229		isSameType func(BoolExpr) bool,
230		getChildren func(BoolExpr) (BoolExpr, BoolExpr),
231	) []config.RuleNode {
232		if isSameType(expr) {
233			left, right := getChildren(expr)
234			var result []config.RuleNode
235			result = append(result, c.flattenBoolExpr(left, isSameType, getChildren)...)
236			result = append(result, c.flattenBoolExpr(right, isSameType, getChildren)...)
237			return result
238		}
239		return []config.RuleNode{c.compileBoolExpr(expr)}
240	}
241	
242	func compileComposerObj(ov ObjectValue) config.RuleCombination {
243		rc := config.RuleCombination{}
244		if t, ok := getStringField(ov.Fields, "type"); ok {
245			rc.Type = t
246		}
247		if n, ok := getStringField(ov.Fields, "name"); ok {
248			rc.Name = n
249		}
250		if op, ok := getStringField(ov.Fields, "operator"); ok {
251			rc.Operator = op
252		}
253		if arr, ok := ov.Fields["conditions"]; ok {
254			if av, ok := arr.(ArrayValue); ok {
255				for _, item := range av.Items {
256					if obj, ok := item.(ObjectValue); ok {
257						rc.Conditions = append(rc.Conditions, compileComposerObj(obj))
258					}
259				}
260			}
261		}
262		return rc
263	}
