11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
12	)
13	
14	// EmitYAML compiles a DSL source string and emits YAML bytes.
15	func EmitYAML(input string) ([]byte, []error) {
16		cfg, errs := Compile(input)
17		if len(errs) > 0 {
18			return nil, errs
19		}
20		yamlBytes, err := EmitYAMLFromConfig(cfg)
21		if err != nil {
22			return nil, []error{err}
23		}
24		return yamlBytes, nil
25	}
26	
27	// EmitYAMLFromConfig marshals a RouterConfig to YAML bytes.
28	func EmitYAMLFromConfig(cfg *config.RouterConfig) ([]byte, error) {
29		if cfg != nil && (len(cfg.KnowledgeBases) > 0 || len(cfg.Entrypoints) > 0 || len(cfg.Recipes) > 1) {
30			canonical := config.CanonicalConfigFromRouterConfig(cfg)
31			return yaml.Marshal(canonical)
32		}
33		return yaml.Marshal(cfg)
34	}
35	
36	// EmitUserYAML emits YAML in the user-friendly nested format (signals/providers)
37	// that matches the config.yaml format used by vllm-serve.
38	// This is the inverse of normalizeYAML.
39	func EmitUserYAML(cfg *config.RouterConfig) ([]byte, error) {
40		if cfg != nil && (len(cfg.KnowledgeBases) > 0 || len(cfg.Entrypoints) > 0 || len(cfg.Recipes) > 1) {
41			canonical := config.CanonicalConfigFromRouterConfig(cfg)
42			return yaml.Marshal(canonical)
43		}
44		// First marshal to flat YAML, then restructure via map manipulation.
45		flatBytes, err := yaml.Marshal(cfg)
46		if err != nil {
47			return nil, err
48		}
49		var raw map[string]interface{}
50		if err := yaml.Unmarshal(flatBytes, &raw); err != nil {
51			return nil, err
52		}
53	
54		denormalizeSignals(raw)
55		denormalizeProviders(raw)
56		pruneZeroValueInfra(raw)
57	
58		return yaml.Marshal(raw)
59	}
60	
61	// denormalizeSignals groups flat signal keys into a nested "signals" section.
62	func denormalizeSignals(raw map[string]interface{}) {
63		signalKeyMap := map[string]string{
64			"keyword_rules":       "keywords",
65			"embedding_rules":     "embeddings",
66			"categories":          "domains",
67			"fact_check_rules":    "fact_check",
68			"user_feedback_rules": "user_feedbacks",
69			"reask_rules":         "reasks",
70			"preference_rules":    "preferences",
71			"language_rules":      "language",
72			"context_rules":       "context",
73			"structure_rules":     "structure",
74			"complexity_rules":    "complexity",
75			"modality_rules":      "modality",
76			"role_bindings":       "authz",
77			"jailbreak":           "jailbreak",
78			"pii":                 "pii",
79			"kb":                  "kb",
80			"conversation":        "conversation",
81			"events":              "events",
82		}
83	
84		signals := make(map[string]interface{})
85		for flatKey, nestedKey := range signalKeyMap {
86			if v, ok := raw[flatKey]; ok {
87				if !isEmptySlice(v) {
88					signals[nestedKey] = v
89				}
90				delete(raw, flatKey)
91			}
92		}
93		if len(signals) > 0 {
94			raw["signals"] = signals
95		}
96	}
97	
98	type endpointInfo struct {
99		name     string
100		address  string
101		port     int
102		weight   interface{}
103		protocol string
104		epType   string
105		apiKey   string
106	}
107	
108	type modelEntry struct {
109		name      string
110		endpoints []endpointInfo
111		config    map[string]interface{}
112	}
113	
114	// denormalizeProviders groups vllm_endpoints + model_config into a nested "providers" section
115	// and reconstructs the user-friendly "models" list.
116	func denormalizeProviders(raw map[string]interface{}) {
117		providers := make(map[string]interface{})
118	
119		// Reconstruct models from vllm_endpoints + model_config
120		endpoints, _ := raw["vllm_endpoints"].([]interface{})
121		modelConfigRaw, _ := raw["model_config"].(map[string]interface{})
122	
123		if len(endpoints) > 0 {
124			models := buildModelsFromEndpoints(endpoints, modelConfigRaw)
125			if len(models) > 0 {
126				providers["models"] = models
127			}
128		}
129		delete(raw, "vllm_endpoints")
130		delete(raw, "model_config")
131	
132		// Hoist simple keys into providers
133		for _, key := range []string{"default_model", "reasoning_families", "default_reasoning_effort"} {
134			if v, ok := raw[key]; ok {
135				providers[key] = v
136				delete(raw, key)
137			}
138		}
139	
140		if len(providers) > 0 {
141			raw["providers"] = providers
142		}
143	}
144	
145	// buildModelsFromEndpoints reconstructs the nested models list from flat endpoints.
146	// normalizeYAML creates endpoint names as "{modelName}_{epName}".
147	// We group by modelName and reconstruct endpoints with address:port → "endpoint" field.
148	func buildModelsFromEndpoints(endpoints []interface{}, modelConfigRaw map[string]interface{}) []interface{} {
149		modelMap, modelOrder := collectModelEntries(endpoints)
150		mergeModelConfig(modelMap, &modelOrder, modelConfigRaw)
151		return buildUserModels(modelMap, modelOrder)
152	}
153	
154	func collectModelEntries(endpoints []interface{}) (map[string]*modelEntry, []string) {
155		modelMap := make(map[string]*modelEntry)
156		var modelOrder []string
157		for _, ep := range endpoints {
158			addEndpointToModelMap(modelMap, &modelOrder, ep)
159		}
160		return modelMap, modelOrder
161	}
162	
163	func addEndpointToModelMap(modelMap map[string]*modelEntry, modelOrder *[]string, ep interface{}) {
164		epMap, ok := ep.(map[string]interface{})
165		if !ok {
166			return
167		}
168		fullName, _ := epMap["name"].(string)
169		modelName, epName := deriveModelAndEndpointNames(epMap, fullName)
170		if modelName == "" {
171			return
172		}
173		me := ensureModelEntry(modelMap, modelOrder, modelName)
174		me.endpoints = append(me.endpoints, endpointInfo{
175			name:     epName,
176			address:  toString(epMap["address"]),
177			port:     toInt(epMap["port"]),
178			weight:   epMap["weight"],
179			protocol: toString(epMap["protocol"]),
180			epType:   toString(epMap["type"]),
181			apiKey:   toString(epMap["api_key"]),
182		})
183	}
184	
185	func deriveModelAndEndpointNames(epMap map[string]interface{}, fullName string) (string, string) {
186		modelName := toString(epMap["model"])
187		epName := "vllm_endpoint"
188		if modelName == "" {
189			return splitEndpointName(fullName)
190		}
191		if strings.HasPrefix(fullName, modelName+"_") {
192			epName = fullName[len(modelName)+1:]
193		}
194		return modelName, epName
195	}
196	
197	func ensureModelEntry(modelMap map[string]*modelEntry, modelOrder *[]string, modelName string) *modelEntry {
198		if me, ok := modelMap[modelName]; ok {
199			return me
200		}
201		me := &modelEntry{name: modelName}
202		modelMap[modelName] = me
203		*modelOrder = append(*modelOrder, modelName)
204		return me
205	}
206	
207	func mergeModelConfig(modelMap map[string]*modelEntry, modelOrder *[]string, modelConfigRaw map[string]interface{}) {
208		for modelName, mcRaw := range modelConfigRaw {
209			mc, ok := mcRaw.(map[string]interface{})
210			if !ok {
211				continue
212			}
213			ensureModelEntry(modelMap, modelOrder, modelName).config = mc
214		}
215	}
216	
217	func buildUserModels(modelMap map[string]*modelEntry, modelOrder []string) []interface{} {
218		models := make([]interface{}, 0, len(modelOrder))
219		for _, modelName := range modelOrder {
220			models = append(models, buildUserModelEntry(modelMap[modelName]))
221		}
222		return models
223	}
224	
225	func buildUserModelEntry(me *modelEntry) map[string]interface{} {
226		m := map[string]interface{}{"name": me.name}
227		for k, v := range me.config {
228			if k == "preferred_endpoints" || isZeroValue(v) {
229				continue
230			}
231			m[k] = v
232		}
233		if endpoints := buildUserEndpoints(me.endpoints); len(endpoints) > 0 {
234			m["endpoints"] = endpoints
235		}
236		return m
237	}
238	
239	func buildUserEndpoints(endpoints []endpointInfo) []interface{} {
240		epList := make([]interface{}, 0, len(endpoints))
241		for _, ep := range endpoints {
242			epOut := map[string]interface{}{"name": ep.name}
243			endpoint := ep.address
244			if ep.port != 0 {
245				endpoint = fmt.Sprintf("%s:%d", ep.address, ep.port)
246			}
247			epOut["endpoint"] = endpoint
248			if ep.weight != nil && !isZeroValue(ep.weight) {
249				epOut["weight"] = ep.weight
250			}
251			if ep.protocol != "" && ep.protocol != "http" {
252				epOut["protocol"] = ep.protocol
253			}
254			if ep.epType != "" {
255				epOut["type"] = ep.epType
256			}
257			if ep.apiKey != "" {
258				epOut["api_key"] = ep.apiKey
259			}
260			epList = append(epList, epOut)
261		}
262		return epList
263	}
264	
265	// splitEndpointName tries to split "modelName_epName" back into parts.
266	// Since model names can contain underscores, we try the last "_" segment as epName.
267	func splitEndpointName(fullName string) (string, string) {
268		idx := strings.LastIndex(fullName, "_")
269		if idx <= 0 {
270			return fullName, ""
271		}
272		return fullName[:idx], fullName[idx+1:]
273	}
274	
275	// pruneZeroValueInfra removes infrastructure config sections that are all zero values.
276	// These are config sections not representable in DSL (embedding_models, classifiers, etc.)
277	func pruneZeroValueInfra(raw map[string]interface{}) {
278		infraKeys := []string{
279			"embedding_models", "classifier",
280			"prompt_guard", "hallucination_mitigation",
281			"feedback_detector", "modality_detector",
282			"semantic_cache", "memory", "response_api",
283			"router_replay", "api", "tools",
284			"config_source", "external_models",
285			"looper", "model_selection", "vector_store",
286			"authz", "ratelimit", "mom_registry",
287			"auto_model_name", "include_config_models_in_list",
288			"clear_route_cache",
289			"image_gen_backends", "provider_profiles",
290			"batch_classification",
291			"observability",
292		}
293		for _, key := range infraKeys {
294			if v, ok := raw[key]; ok {
295				if isZeroValue(v) {
296					delete(raw, key)
297				}
298			}
299		}
300	
301		// Also remove strategy if empty
302		if v, ok := raw["strategy"]; ok {
303			if s, ok := v.(string); ok && s == "" {
304				delete(raw, "strategy")
305			}
306		}
307	}
308	
309	// isEmptySlice returns true if v is a nil or empty slice.
310	func isEmptySlice(v interface{}) bool {
311		if v == nil {
312			return true
313		}
314		if s, ok := v.([]interface{}); ok {
315			return len(s) == 0
316		}
317		return false
318	}
319	
320	// isZeroValue returns true for Go zero values after YAML round-trip.
321	func isZeroValue(v interface{}) bool {
322		if v == nil {
323			return true
324		}
325		switch val := v.(type) {
326		case bool:
327			return !val
328		case int:
329			return val == 0
330		case float64:
331			return val == 0
332		case string:
333			return val == ""
334		case []interface{}:
335			return len(val) == 0
336		case map[string]interface{}:
337			if len(val) == 0 {
338				return true
339			}
340			// Check if all values in map are zero
341			for _, mv := range val {
342				if !isZeroValue(mv) {
343					return false
344				}
345			}
346			return true
347		}
348		return false
349	}
350	
351	// toInt converts interface{} to int for port numbers.
352	func toInt(v interface{}) int {
353		switch val := v.(type) {
354		case int:
355			return val
356		case float64:
357			return int(val)
358		case int64:
359			return int(val)
360		}
361		return 0
362	}
363	
364	func toString(v interface{}) string {
365		if s, ok := v.(string); ok {
366			return s
367		}
368		return ""
369	}
370	
371	// EmitUserYAMLOrdered emits YAML in user-friendly format with a controlled key order
372	// matching the canonical config.yaml layout.
373	func EmitUserYAMLOrdered(cfg *config.RouterConfig) ([]byte, error) {
374		flatBytes, err := yaml.Marshal(cfg)
375		if err != nil {
376			return nil, err
377		}
378		var raw map[string]interface{}
379		if unmarshalErr := yaml.Unmarshal(flatBytes, &raw); unmarshalErr != nil {
380			return nil, unmarshalErr
381		}
382	
383		denormalizeSignals(raw)
384		denormalizeProviders(raw)
385		pruneZeroValueInfra(raw)
386	
387		// Build ordered YAML document
388		doc := &yaml.Node{Kind: yaml.DocumentNode}
389		mapNode := buildOrderedMap(raw)
390		doc.Content = append(doc.Content, mapNode)
391	
392		out, err := yaml.Marshal(doc)
393		if err != nil {
394			return nil, err
395		}
396		return out, nil
397	}
398	
399	// buildOrderedMap creates a yaml.Node mapping with keys in the canonical config.yaml order.
400	func buildOrderedMap(raw map[string]interface{}) *yaml.Node {
401		// Canonical key order for top-level config
402		keyOrder := []string{
403			"listeners",
404			"signals",
405			"decisions",
406			"providers",
407			"observability",
408			"strategy",
409		}
410	
411		mapNode := &yaml.Node{Kind: yaml.MappingNode}
412	
413		// Add keys in order
414		added := make(map[string]bool)
415		for _, key := range keyOrder {
416			if v, ok := raw[key]; ok {
417				addKeyValue(mapNode, key, v)
418				added[key] = true
419			}
420		}
421	
422		// Add remaining keys alphabetically
423		var remaining []string
424		for k := range raw {
425			if !added[k] {
426				remaining = append(remaining, k)
427			}
428		}
429		sort.Strings(remaining)
430		for _, key := range remaining {
431			addKeyValue(mapNode, key, raw[key])
432		}
433	
434		return mapNode
435	}
436	
437	// addKeyValue adds a key-value pair to a yaml MappingNode.
438	func addKeyValue(mapNode *yaml.Node, key string, value interface{}) {
439		keyNode := &yaml.Node{Kind: yaml.ScalarNode, Value: key, Tag: "!!str"}
440		valNode := &yaml.Node{}
441		valBytes, _ := yaml.Marshal(value)
442		_ = yaml.Unmarshal(valBytes, valNode)
443		// yaml.Unmarshal wraps in a document node; unwrap it
444		if valNode.Kind == yaml.DocumentNode && len(valNode.Content) > 0 {
445			valNode = valNode.Content[0]
446		}
447		mapNode.Content = append(mapNode.Content, keyNode, valNode)
448	}
449	
450	// EmitCRD wraps a RouterConfig in a SemanticRouter CRD envelope matching the
451	// Operator's SemanticRouterSpec structure (vllm.ai/v1alpha1 SemanticRouter).
452	//
453	// The mapping is:
454	//
455	//	spec.config      ← routing logic (decisions, strategy, reasoning_families,
456	//	                   complexity_rules, classifier, prompt_guard, semantic_cache, etc.)
457	//	spec.vllmEndpoints ← model backends converted to K8s-native service references
458	//
459	// Signal rules (keyword_rules, embedding_rules, categories, etc.) that the CRD
460	// does NOT model are preserved in spec.config as extra fields, so the output is
461	// self-contained and can be used with a ConfigMap-based deployment.
462	func EmitCRD(cfg *config.RouterConfig, name, namespace string) ([]byte, error) {
463		if namespace == "" {
464			namespace = "default"
465		}
466	
467		// Build spec.config from RouterConfig fields
468		configSpec := buildCRDConfigSpec(cfg)
469	
470		// Build spec.vllmEndpoints from flat vllm_endpoints + model_config
471		vllmEndpoints := buildCRDVLLMEndpoints(cfg)
472	
473		spec := map[string]interface{}{
474			"config": configSpec,
475		}
476		if len(vllmEndpoints) > 0 {
477			spec["vllmEndpoints"] = vllmEndpoints
478		}
479	
480		crd := map[string]interface{}{
481			"apiVersion": "vllm.ai/v1alpha1",
482			"kind":       "SemanticRouter",
483			"metadata": map[string]interface{}{
484				"name":      name,
485				"namespace": namespace,
486			},
487			"spec": spec,
488		}
489	
490		// Marshal, then prune zero-value leaves for a clean output
491		rawBytes, err := yaml.Marshal(crd)
492		if err != nil {
493			return nil, err
494		}
495		var raw map[string]interface{}
496		if err := yaml.Unmarshal(rawBytes, &raw); err != nil {
497			return nil, err
498		}
499		pruneZeroValues(raw)
500	
501		// Build ordered output: apiVersion, kind, metadata, spec
502		doc := &yaml.Node{Kind: yaml.DocumentNode}
503		mapNode := &yaml.Node{Kind: yaml.MappingNode}
504		for _, key := range []string{"apiVersion", "kind", "metadata", "spec"} {
505			if v, ok := raw[key]; ok {
506				addKeyValue(mapNode, key, v)
507			}
508		}
509		doc.Content = append(doc.Content, mapNode)
510		return yaml.Marshal(doc)
511	}
512	
513	// buildCRDConfigSpec constructs the CRD spec.config map from RouterConfig.
514	// It mirrors the Operator's ConfigSpec structure:
515	//   - decisions, strategy, complexity_rules, reasoning_families, default_reasoning_effort
516	//   - embedding_models, classifier, prompt_guard, semantic_cache, tools, observability, api
517	//   - Signal rules not in ConfigSpec are included as extra keys for completeness
518	func buildCRDConfigSpec(cfg *config.RouterConfig) map[string]interface{} {
519		// Marshal the full RouterConfig to a flat map first
520		flatBytes, _ := yaml.Marshal(cfg)
521		var flat map[string]interface{}
522		_ = yaml.Unmarshal(flatBytes, &flat)
523	
524		configSpec := make(map[string]interface{})
525	
526		// --- Fields that belong in ConfigSpec (per semanticrouter_types.go) ---
527	
528		// Routing logic
529		moveKey(flat, configSpec, "decisions")
530		moveKey(flat, configSpec, "strategy")
531		moveKey(flat, configSpec, "complexity_rules")
532		moveKey(flat, configSpec, "reasoning_families")
533		moveKey(flat, configSpec, "default_reasoning_effort")
534		moveKey(flat, configSpec, "default_model")
535	
536		// Infrastructure configs that ConfigSpec supports
537		moveKey(flat, configSpec, "embedding_models")
538		moveKey(flat, configSpec, "classifier")
539		moveKey(flat, configSpec, "prompt_guard")
540		moveKey(flat, configSpec, "semantic_cache")
541		moveKey(flat, configSpec, "tools")
542		moveKey(flat, configSpec, "api")
543		moveKey(flat, configSpec, "observability")
544	
545		// --- Signal rules: not in ConfigSpec but essential for routing ---
546		// Include them in config so the CR is self-contained
547		signalKeys := []string{
548			"keyword_rules", "embedding_rules", "categories",
549			"fact_check_rules", "user_feedback_rules", "reask_rules", "preference_rules",
550			"language_rules", "context_rules", "structure_rules",
551			"modality_rules", "role_bindings", "jailbreak", "pii",
552			"kb", "conversation", "events",
553		}
554		for _, key := range signalKeys {
555			moveKey(flat, configSpec, key)
556		}
557	
558		return configSpec
559	}
560	
561	// buildCRDVLLMEndpoints converts flat vllm_endpoints + model_config into the
562	// CRD's VLLMEndpointSpec format with K8s-native backend references.
563	func buildCRDVLLMEndpoints(cfg *config.RouterConfig) []map[string]interface{} {
564		if len(cfg.VLLMEndpoints) == 0 {
565			return nil
566		}
567	
568		// Build model → reasoning_family lookup from model_config
569		reasoningFamilyLookup := make(map[string]string)
570		for modelName, mc := range cfg.ModelConfig {
571			if mc.ReasoningFamily != "" {
572				reasoningFamilyLookup[modelName] = mc.ReasoningFamily
573			}
574		}
575	
576		var endpoints []map[string]interface{}
577		for _, ep := range cfg.VLLMEndpoints {
578			modelName := ep.Model
579			if modelName == "" {
580				// Try to extract from endpoint name pattern: modelName_epName
581				modelName, _ = splitEndpointName(ep.Name)
582			}
583	
584			entry := map[string]interface{}{
585				"name":  ep.Name,
586				"model": modelName,
587			}
588	
589			// Add reasoning family from model_config if available
590			if rf, ok := reasoningFamilyLookup[modelName]; ok {
591				entry["reasoningFamily"] = rf
592			}
593	
594			// Build backend spec: use type=service with the address/port
595			backend := map[string]interface{}{
596				"type": "service",
597				"service": map[string]interface{}{
598					"name": ep.Address,
599					"port": ep.Port,
600				},
601			}
602			entry["backend"] = backend
603	
604			if ep.Weight > 0 && ep.Weight != 1 {
605				entry["weight"] = ep.Weight
606			}
607	
608			endpoints = append(endpoints, entry)
609		}
610		return endpoints
611	}
612	
613	// moveKey moves a key from src to dst if it exists and is non-zero.
614	func moveKey(src, dst map[string]interface{}, key string) {
615		if v, ok := src[key]; ok {
616			if !isZeroValue(v) {
617				dst[key] = v
618			}
619			delete(src, key)
620		}
621	}
622	
623	// EmitHelm emits a Helm values fragment that only carries the DSL-owned routing
624	// surface under the chart's canonical `config:` key.
625	func EmitHelm(cfg *config.RouterConfig) ([]byte, error) {
626		type helmValuesConfig struct {
627			Version string                  `yaml:"version"`
628			Routing config.CanonicalRouting `yaml:"routing"`
629		}
630	
631		values := map[string]interface{}{
632			"config": helmValuesConfig{
633				Version: "v0.3",
634				Routing: config.CanonicalRoutingFromRouterConfig(cfg),
635			},
636		}
637	
638		doc := &yaml.Node{Kind: yaml.DocumentNode}
639		mapNode := &yaml.Node{Kind: yaml.MappingNode}
640		addKeyValue(mapNode, "config", values["config"])
641		doc.Content = append(doc.Content, mapNode)
642	
643		return yaml.Marshal(doc)
644	}
645	
646	// MergeRoutingIntoBase takes the DSL-compiled RouterConfig and a base YAML
647	// document (containing version, listeners, providers), replaces the routing
648	// section with the compiled one, and emits a complete canonical config YAML.
649	func MergeRoutingIntoBase(cfg *config.RouterConfig, baseYAML []byte) ([]byte, error) {
650		var base map[string]interface{}
651		if err := yaml.Unmarshal(baseYAML, &base); err != nil {
652			return nil, fmt.Errorf("failed to parse base YAML: %w", err)
653		}
654	
655		canonical := config.CanonicalConfigFromRouterConfig(cfg)
656		routingBytes, err := yaml.Marshal(canonical.Routing)
657		if err != nil {
658			return nil, fmt.Errorf("failed to marshal routing: %w", err)
659		}
660		var routing interface{}
661		if err := yaml.Unmarshal(routingBytes, &routing); err != nil {
662			return nil, fmt.Errorf("failed to re-parse routing: %w", err)
663		}
664	
665		base["routing"] = routing
666		if len(canonical.Entrypoints) > 0 {
667			base["entrypoints"] = canonical.Entrypoints
668		} else {
669			delete(base, "entrypoints")
670		}
671		if len(canonical.Recipes) > 0 {
672			base["recipes"] = canonical.Recipes
673		} else {
674			delete(base, "recipes")
675		}
676	
677		doc := &yaml.Node{Kind: yaml.DocumentNode}
678		mapNode := &yaml.Node{Kind: yaml.MappingNode}
679		canonicalOrder := []string{"version", "listeners", "providers", "routing", "entrypoints", "recipes", "global"}
680		added := make(map[string]bool)
681		for _, key := range canonicalOrder {
682			if v, ok := base[key]; ok {
683				addKeyValue(mapNode, key, v)
684				added[key] = true
685			}
686		}
687		var remaining []string
688		for k := range base {
689			if !added[k] {
690				remaining = append(remaining, k)
691			}
692		}
693		sort.Strings(remaining)
694		for _, key := range remaining {
695			addKeyValue(mapNode, key, base[key])
696		}
697		doc.Content = append(doc.Content, mapNode)
698		return marshalYAMLIndent2(doc)
699	}
700	
701	// marshalYAMLIndent2 encodes a yaml.Node with 2-space indentation to match
702	// the project's yamllint configuration.
703	func marshalYAMLIndent2(node *yaml.Node) ([]byte, error) {
704		var buf bytes.Buffer
705		enc := yaml.NewEncoder(&buf)
706		enc.SetIndent(2)
707		if err := enc.Encode(node); err != nil {
708			return nil, err
709		}
710		if err := enc.Close(); err != nil {
711			return nil, err
712		}
713		return buf.Bytes(), nil
714	}
715	
716	// pruneZeroValues recursively removes zero-value entries from a nested map.
717	func pruneZeroValues(m map[string]interface{}) {
718		for k, v := range m {
719			switch val := v.(type) {
720			case map[string]interface{}:
721				pruneZeroValues(val)
722				if len(val) == 0 {
723					delete(m, k)
724				}
725			case []interface{}:
726				if len(val) == 0 {
727					delete(m, k)
728				}
729			default:
730				if isZeroValue(v) {
731					delete(m, k)
732				}
733			}
734		}
735	}
