package dsl

import (
	"bytes"
	"fmt"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

// EmitYAML compiles a DSL source string and emits YAML bytes.
func EmitYAML(input string) ([]byte, []error) {
	cfg, errs := Compile(input)
	if len(errs) > 0 {
		return nil, errs
	}
	yamlBytes, err := EmitYAMLFromConfig(cfg)
	if err != nil {
		return nil, []error{err}
	}
	return yamlBytes, nil
}

// EmitYAMLFromConfig marshals a RouterConfig to YAML bytes.
func EmitYAMLFromConfig(cfg *config.RouterConfig) ([]byte, error) {
	if cfg != nil && (len(cfg.KnowledgeBases) > 0 || len(cfg.Entrypoints) > 0 || len(cfg.Recipes) > 1) {
		canonical := config.CanonicalConfigFromRouterConfig(cfg)
		return yaml.Marshal(canonical)
	}
	return yaml.Marshal(cfg)
}

// EmitUserYAML emits YAML in the user-friendly nested format (signals/providers)
// that matches the config.yaml format used by vllm-serve.
// This is the inverse of normalizeYAML.
func EmitUserYAML(cfg *config.RouterConfig) ([]byte, error) {
	if cfg != nil && (len(cfg.KnowledgeBases) > 0 || len(cfg.Entrypoints) > 0 || len(cfg.Recipes) > 1) {
		canonical := config.CanonicalConfigFromRouterConfig(cfg)
		return yaml.Marshal(canonical)
	}
	// First marshal to flat YAML, then restructure via map manipulation.
	flatBytes, err := yaml.Marshal(cfg)
	if err != nil {
		return nil, err
	}
	var raw map[string]interface{}
	if err := yaml.Unmarshal(flatBytes, &raw); err != nil {
		return nil, err
	}

	denormalizeSignals(raw)
	denormalizeProviders(raw)
	pruneZeroValueInfra(raw)

	return yaml.Marshal(raw)
}

// denormalizeSignals groups flat signal keys into a nested "signals" section.
func denormalizeSignals(raw map[string]interface{}) {
	signalKeyMap := map[string]string{
		"keyword_rules":       "keywords",
		"embedding_rules":     "embeddings",
		"categories":          "domains",
		"fact_check_rules":    "fact_check",
		"user_feedback_rules": "user_feedbacks",
		"reask_rules":         "reasks",
		"preference_rules":    "preferences",
		"language_rules":      "language",
		"context_rules":       "context",
		"structure_rules":     "structure",
		"complexity_rules":    "complexity",
		"modality_rules":      "modality",
		"role_bindings":       "authz",
		"jailbreak":           "jailbreak",
		"pii":                 "pii",
		"kb":                  "kb",
		"conversation":        "conversation",
		"events":              "events",
	}

	signals := make(map[string]interface{})
	for flatKey, nestedKey := range signalKeyMap {
		if v, ok := raw[flatKey]; ok {
			if !isEmptySlice(v) {
				signals[nestedKey] = v
			}
			delete(raw, flatKey)
		}
	}
	if len(signals) > 0 {
		raw["signals"] = signals
	}
}

type endpointInfo struct {
	name     string
	address  string
	port     int
	weight   interface{}
	protocol string
	epType   string
	apiKey   string
}

type modelEntry struct {
	name      string
	endpoints []endpointInfo
	config    map[string]interface{}
}

// denormalizeProviders groups vllm_endpoints + model_config into a nested "providers" section
// and reconstructs the user-friendly "models" list.
func denormalizeProviders(raw map[string]interface{}) {
	providers := make(map[string]interface{})

	// Reconstruct models from vllm_endpoints + model_config
	endpoints, _ := raw["vllm_endpoints"].([]interface{})
	modelConfigRaw, _ := raw["model_config"].(map[string]interface{})

	if len(endpoints) > 0 {
		models := buildModelsFromEndpoints(endpoints, modelConfigRaw)
		if len(models) > 0 {
			providers["models"] = models
		}
	}
	delete(raw, "vllm_endpoints")
	delete(raw, "model_config")

	// Hoist simple keys into providers
	for _, key := range []string{"default_model", "reasoning_families", "default_reasoning_effort"} {
		if v, ok := raw[key]; ok {
			providers[key] = v
			delete(raw, key)
		}
	}

	if len(providers) > 0 {
		raw["providers"] = providers
	}
}

// buildModelsFromEndpoints reconstructs the nested models list from flat endpoints.
// normalizeYAML creates endpoint names as "{modelName}_{epName}".
// We group by modelName and reconstruct endpoints with address:port → "endpoint" field.
func buildModelsFromEndpoints(endpoints []interface{}, modelConfigRaw map[string]interface{}) []interface{} {
	modelMap, modelOrder := collectModelEntries(endpoints)
	mergeModelConfig(modelMap, &modelOrder, modelConfigRaw)
	return buildUserModels(modelMap, modelOrder)
}

func collectModelEntries(endpoints []interface{}) (map[string]*modelEntry, []string) {
	modelMap := make(map[string]*modelEntry)
	var modelOrder []string
	for _, ep := range endpoints {
		addEndpointToModelMap(modelMap, &modelOrder, ep)
	}
	return modelMap, modelOrder
}

func addEndpointToModelMap(modelMap map[string]*modelEntry, modelOrder *[]string, ep interface{}) {
	epMap, ok := ep.(map[string]interface{})
	if !ok {
		return
	}
	fullName, _ := epMap["name"].(string)
	modelName, epName := deriveModelAndEndpointNames(epMap, fullName)
	if modelName == "" {
		return
	}
	me := ensureModelEntry(modelMap, modelOrder, modelName)
	me.endpoints = append(me.endpoints, endpointInfo{
		name:     epName,
		address:  toString(epMap["address"]),
		port:     toInt(epMap["port"]),
		weight:   epMap["weight"],
		protocol: toString(epMap["protocol"]),
		epType:   toString(epMap["type"]),
		apiKey:   toString(epMap["api_key"]),
	})
}

func deriveModelAndEndpointNames(epMap map[string]interface{}, fullName string) (string, string) {
	modelName := toString(epMap["model"])
	epName := "vllm_endpoint"
	if modelName == "" {
		return splitEndpointName(fullName)
	}
	if strings.HasPrefix(fullName, modelName+"_") {
		epName = fullName[len(modelName)+1:]
	}
	return modelName, epName
}

func ensureModelEntry(modelMap map[string]*modelEntry, modelOrder *[]string, modelName string) *modelEntry {
	if me, ok := modelMap[modelName]; ok {
		return me
	}
	me := &modelEntry{name: modelName}
	modelMap[modelName] = me
	*modelOrder = append(*modelOrder, modelName)
	return me
}

func mergeModelConfig(modelMap map[string]*modelEntry, modelOrder *[]string, modelConfigRaw map[string]interface{}) {
	for modelName, mcRaw := range modelConfigRaw {
		mc, ok := mcRaw.(map[string]interface{})
		if !ok {
			continue
		}
		ensureModelEntry(modelMap, modelOrder, modelName).config = mc
	}
}

func buildUserModels(modelMap map[string]*modelEntry, modelOrder []string) []interface{} {
	models := make([]interface{}, 0, len(modelOrder))
	for _, modelName := range modelOrder {
		models = append(models, buildUserModelEntry(modelMap[modelName]))
	}
	return models
}

func buildUserModelEntry(me *modelEntry) map[string]interface{} {
	m := map[string]interface{}{"name": me.name}
	for k, v := range me.config {
		if k == "preferred_endpoints" || isZeroValue(v) {
			continue
		}
		m[k] = v
	}
	if endpoints := buildUserEndpoints(me.endpoints); len(endpoints) > 0 {
		m["endpoints"] = endpoints
	}
	return m
}

func buildUserEndpoints(endpoints []endpointInfo) []interface{} {
	epList := make([]interface{}, 0, len(endpoints))
	for _, ep := range endpoints {
		epOut := map[string]interface{}{"name": ep.name}
		endpoint := ep.address
		if ep.port != 0 {
			endpoint = fmt.Sprintf("%s:%d", ep.address, ep.port)
		}
		epOut["endpoint"] = endpoint
		if ep.weight != nil && !isZeroValue(ep.weight) {
			epOut["weight"] = ep.weight
		}
		if ep.protocol != "" && ep.protocol != "http" {
			epOut["protocol"] = ep.protocol
		}
		if ep.epType != "" {
			epOut["type"] = ep.epType
		}
		if ep.apiKey != "" {
			epOut["api_key"] = ep.apiKey
		}
		epList = append(epList, epOut)
	}
	return epList
}

// splitEndpointName tries to split "modelName_epName" back into parts.
// Since model names can contain underscores, we try the last "_" segment as epName.
func splitEndpointName(fullName string) (string, string) {
	idx := strings.LastIndex(fullName, "_")
	if idx <= 0 {
		return fullName, ""
	}
	return fullName[:idx], fullName[idx+1:]
}

// pruneZeroValueInfra removes infrastructure config sections that are all zero values.
// These are config sections not representable in DSL (embedding_models, classifiers, etc.)
func pruneZeroValueInfra(raw map[string]interface{}) {
	infraKeys := []string{
		"embedding_models", "classifier",
		"prompt_guard", "hallucination_mitigation",
		"feedback_detector", "modality_detector",
		"semantic_cache", "memory", "response_api",
		"router_replay", "api", "tools",
		"config_source", "external_models",
		"looper", "model_selection", "vector_store",
		"authz", "ratelimit", "mom_registry",
		"auto_model_name", "include_config_models_in_list",
		"clear_route_cache",
		"image_gen_backends", "provider_profiles",
		"batch_classification",
		"observability",
	}
	for _, key := range infraKeys {
		if v, ok := raw[key]; ok {
			if isZeroValue(v) {
				delete(raw, key)
			}
		}
	}

	// Also remove strategy if empty
	if v, ok := raw["strategy"]; ok {
		if s, ok := v.(string); ok && s == "" {
			delete(raw, "strategy")
		}
	}
}

// isEmptySlice returns true if v is a nil or empty slice.
func isEmptySlice(v interface{}) bool {
	if v == nil {
		return true
	}
	if s, ok := v.([]interface{}); ok {
		return len(s) == 0
	}
	return false
}

// isZeroValue returns true for Go zero values after YAML round-trip.
func isZeroValue(v interface{}) bool {
	if v == nil {
		return true
	}
	switch val := v.(type) {
	case bool:
		return !val
	case int:
		return val == 0
	case float64:
		return val == 0
	case string:
		return val == ""
	case []interface{}:
		return len(val) == 0
	case map[string]interface{}:
		if len(val) == 0 {
			return true
		}
		// Check if all values in map are zero
		for _, mv := range val {
			if !isZeroValue(mv) {
				return false
			}
		}
		return true
	}
	return false
}

// toInt converts interface{} to int for port numbers.
func toInt(v interface{}) int {
	switch val := v.(type) {
	case int:
		return val
	case float64:
		return int(val)
	case int64:
		return int(val)
	}
	return 0
}

func toString(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}

// EmitUserYAMLOrdered emits YAML in user-friendly format with a controlled key order
// matching the canonical config.yaml layout.
func EmitUserYAMLOrdered(cfg *config.RouterConfig) ([]byte, error) {
	flatBytes, err := yaml.Marshal(cfg)
	if err != nil {
		return nil, err
	}
	var raw map[string]interface{}
	if unmarshalErr := yaml.Unmarshal(flatBytes, &raw); unmarshalErr != nil {
		return nil, unmarshalErr
	}

	denormalizeSignals(raw)
	denormalizeProviders(raw)
	pruneZeroValueInfra(raw)

	// Build ordered YAML document
	doc := &yaml.Node{Kind: yaml.DocumentNode}
	mapNode := buildOrderedMap(raw)
	doc.Content = append(doc.Content, mapNode)

	out, err := yaml.Marshal(doc)
	if err != nil {
		return nil, err
	}
	return out, nil
}

// buildOrderedMap creates a yaml.Node mapping with keys in the canonical config.yaml order.
func buildOrderedMap(raw map[string]interface{}) *yaml.Node {
	// Canonical key order for top-level config
	keyOrder := []string{
		"listeners",
		"signals",
		"decisions",
		"providers",
		"observability",
		"strategy",
	}

	mapNode := &yaml.Node{Kind: yaml.MappingNode}

	// Add keys in order
	added := make(map[string]bool)
	for _, key := range keyOrder {
		if v, ok := raw[key]; ok {
			addKeyValue(mapNode, key, v)
			added[key] = true
		}
	}

	// Add remaining keys alphabetically
	var remaining []string
	for k := range raw {
		if !added[k] {
			remaining = append(remaining, k)
		}
	}
	sort.Strings(remaining)
	for _, key := range remaining {
		addKeyValue(mapNode, key, raw[key])
	}

	return mapNode
}

// addKeyValue adds a key-value pair to a yaml MappingNode.
func addKeyValue(mapNode *yaml.Node, key string, value interface{}) {
	keyNode := &yaml.Node{Kind: yaml.ScalarNode, Value: key, Tag: "!!str"}
	valNode := &yaml.Node{}
	valBytes, _ := yaml.Marshal(value)
	_ = yaml.Unmarshal(valBytes, valNode)
	// yaml.Unmarshal wraps in a document node; unwrap it
	if valNode.Kind == yaml.DocumentNode && len(valNode.Content) > 0 {
		valNode = valNode.Content[0]
	}
	mapNode.Content = append(mapNode.Content, keyNode, valNode)
}

// EmitCRD wraps a RouterConfig in a SemanticRouter CRD envelope matching the
// Operator's SemanticRouterSpec structure (vllm.ai/v1alpha1 SemanticRouter).
//
// The mapping is:
//
//	spec.config      ← routing logic (decisions, strategy, reasoning_families,
//	                   complexity_rules, classifier, prompt_guard, semantic_cache, etc.)
//	spec.vllmEndpoints ← model backends converted to K8s-native service references
//
// Signal rules (keyword_rules, embedding_rules, categories, etc.) that the CRD
// does NOT model are preserved in spec.config as extra fields, so the output is
// self-contained and can be used with a ConfigMap-based deployment.
func EmitCRD(cfg *config.RouterConfig, name, namespace string) ([]byte, error) {
	if namespace == "" {
		namespace = "default"
	}

	// Build spec.config from RouterConfig fields
	configSpec := buildCRDConfigSpec(cfg)

	// Build spec.vllmEndpoints from flat vllm_endpoints + model_config
	vllmEndpoints := buildCRDVLLMEndpoints(cfg)

	spec := map[string]interface{}{
		"config": configSpec,
	}
	if len(vllmEndpoints) > 0 {
		spec["vllmEndpoints"] = vllmEndpoints
	}

	crd := map[string]interface{}{
		"apiVersion": "vllm.ai/v1alpha1",
		"kind":       "SemanticRouter",
		"metadata": map[string]interface{}{
			"name":      name,
			"namespace": namespace,
		},
		"spec": spec,
	}

	// Marshal, then prune zero-value leaves for a clean output
	rawBytes, err := yaml.Marshal(crd)
	if err != nil {
		return nil, err
	}
	var raw map[string]interface{}
	if err := yaml.Unmarshal(rawBytes, &raw); err != nil {
		return nil, err
	}
	pruneZeroValues(raw)

	// Build ordered output: apiVersion, kind, metadata, spec
	doc := &yaml.Node{Kind: yaml.DocumentNode}
	mapNode := &yaml.Node{Kind: yaml.MappingNode}
	for _, key := range []string{"apiVersion", "kind", "metadata", "spec"} {
		if v, ok := raw[key]; ok {
			addKeyValue(mapNode, key, v)
		}
	}
	doc.Content = append(doc.Content, mapNode)
	return yaml.Marshal(doc)
}

// buildCRDConfigSpec constructs the CRD spec.config map from RouterConfig.
// It mirrors the Operator's ConfigSpec structure:
//   - decisions, strategy, complexity_rules, reasoning_families, default_reasoning_effort
//   - embedding_models, classifier, prompt_guard, semantic_cache, tools, observability, api
//   - Signal rules not in ConfigSpec are included as extra keys for completeness
func buildCRDConfigSpec(cfg *config.RouterConfig) map[string]interface{} {
	// Marshal the full RouterConfig to a flat map first
	flatBytes, _ := yaml.Marshal(cfg)
	var flat map[string]interface{}
	_ = yaml.Unmarshal(flatBytes, &flat)

	configSpec := make(map[string]interface{})

	// --- Fields that belong in ConfigSpec (per semanticrouter_types.go) ---

	// Routing logic
	moveKey(flat, configSpec, "decisions")
	moveKey(flat, configSpec, "strategy")
	moveKey(flat, configSpec, "complexity_rules")
	moveKey(flat, configSpec, "reasoning_families")
	moveKey(flat, configSpec, "default_reasoning_effort")
	moveKey(flat, configSpec, "default_model")

	// Infrastructure configs that ConfigSpec supports
	moveKey(flat, configSpec, "embedding_models")
	moveKey(flat, configSpec, "classifier")
	moveKey(flat, configSpec, "prompt_guard")
	moveKey(flat, configSpec, "semantic_cache")
	moveKey(flat, configSpec, "tools")
	moveKey(flat, configSpec, "api")
	moveKey(flat, configSpec, "observability")

	// --- Signal rules: not in ConfigSpec but essential for routing ---
	// Include them in config so the CR is self-contained
	signalKeys := []string{
		"keyword_rules", "embedding_rules", "categories",
		"fact_check_rules", "user_feedback_rules", "reask_rules", "preference_rules",
		"language_rules", "context_rules", "structure_rules",
		"modality_rules", "role_bindings", "jailbreak", "pii",
		"kb", "conversation", "events",
	}
	for _, key := range signalKeys {
		moveKey(flat, configSpec, key)
	}

	return configSpec
}

// buildCRDVLLMEndpoints converts flat vllm_endpoints + model_config into the
// CRD's VLLMEndpointSpec format with K8s-native backend references.
func buildCRDVLLMEndpoints(cfg *config.RouterConfig) []map[string]interface{} {
	if len(cfg.VLLMEndpoints) == 0 {
		return nil
	}

	// Build model → reasoning_family lookup from model_config
	reasoningFamilyLookup := make(map[string]string)
	for modelName, mc := range cfg.ModelConfig {
		if mc.ReasoningFamily != "" {
			reasoningFamilyLookup[modelName] = mc.ReasoningFamily
		}
	}

	var endpoints []map[string]interface{}
	for _, ep := range cfg.VLLMEndpoints {
		modelName := ep.Model
		if modelName == "" {
			// Try to extract from endpoint name pattern: modelName_epName
			modelName, _ = splitEndpointName(ep.Name)
		}

		entry := map[string]interface{}{
			"name":  ep.Name,
			"model": modelName,
		}

		// Add reasoning family from model_config if available
		if rf, ok := reasoningFamilyLookup[modelName]; ok {
			entry["reasoningFamily"] = rf
		}

		// Build backend spec: use type=service with the address/port
		backend := map[string]interface{}{
			"type": "service",
			"service": map[string]interface{}{
				"name": ep.Address,
				"port": ep.Port,
			},
		}
		entry["backend"] = backend

		if ep.Weight > 0 && ep.Weight != 1 {
			entry["weight"] = ep.Weight
		}

		endpoints = append(endpoints, entry)
	}
	return endpoints
}

// moveKey moves a key from src to dst if it exists and is non-zero.
func moveKey(src, dst map[string]interface{}, key string) {
	if v, ok := src[key]; ok {
		if !isZeroValue(v) {
			dst[key] = v
		}
		delete(src, key)
	}
}

// EmitHelm emits a Helm values fragment that only carries the DSL-owned routing
// surface under the chart's canonical `config:` key.
func EmitHelm(cfg *config.RouterConfig) ([]byte, error) {
	type helmValuesConfig struct {
		Version string                  `yaml:"version"`
		Routing config.CanonicalRouting `yaml:"routing"`
	}

	values := map[string]interface{}{
		"config": helmValuesConfig{
			Version: "v0.3",
			Routing: config.CanonicalRoutingFromRouterConfig(cfg),
		},
	}

	doc := &yaml.Node{Kind: yaml.DocumentNode}
	mapNode := &yaml.Node{Kind: yaml.MappingNode}
	addKeyValue(mapNode, "config", values["config"])
	doc.Content = append(doc.Content, mapNode)

	return yaml.Marshal(doc)
}

// MergeRoutingIntoBase takes the DSL-compiled RouterConfig and a base YAML
// document (containing version, listeners, providers), replaces the routing
// section with the compiled one, and emits a complete canonical config YAML.
func MergeRoutingIntoBase(cfg *config.RouterConfig, baseYAML []byte) ([]byte, error) {
	var base map[string]interface{}
	if err := yaml.Unmarshal(baseYAML, &base); err != nil {
		return nil, fmt.Errorf("failed to parse base YAML: %w", err)
	}

	canonical := config.CanonicalConfigFromRouterConfig(cfg)
	routingBytes, err := yaml.Marshal(canonical.Routing)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal routing: %w", err)
	}
	var routing interface{}
	if err := yaml.Unmarshal(routingBytes, &routing); err != nil {
		return nil, fmt.Errorf("failed to re-parse routing: %w", err)
	}

	base["routing"] = routing
	if len(canonical.Entrypoints) > 0 {
		base["entrypoints"] = canonical.Entrypoints
	} else {
		delete(base, "entrypoints")
	}
	if len(canonical.Recipes) > 0 {
		base["recipes"] = canonical.Recipes
	} else {
		delete(base, "recipes")
	}

	doc := &yaml.Node{Kind: yaml.DocumentNode}
	mapNode := &yaml.Node{Kind: yaml.MappingNode}
	canonicalOrder := []string{"version", "listeners", "providers", "routing", "entrypoints", "recipes", "global"}
	added := make(map[string]bool)
	for _, key := range canonicalOrder {
		if v, ok := base[key]; ok {
			addKeyValue(mapNode, key, v)
			added[key] = true
		}
	}
	var remaining []string
	for k := range base {
		if !added[k] {
			remaining = append(remaining, k)
		}
	}
	sort.Strings(remaining)
	for _, key := range remaining {
		addKeyValue(mapNode, key, base[key])
	}
	doc.Content = append(doc.Content, mapNode)
	return marshalYAMLIndent2(doc)
}

// marshalYAMLIndent2 encodes a yaml.Node with 2-space indentation to match
// the project's yamllint configuration.
func marshalYAMLIndent2(node *yaml.Node) ([]byte, error) {
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(node); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// pruneZeroValues recursively removes zero-value entries from a nested map.
func pruneZeroValues(m map[string]interface{}) {
	for k, v := range m {
		switch val := v.(type) {
		case map[string]interface{}:
			pruneZeroValues(val)
			if len(val) == 0 {
				delete(m, k)
			}
		case []interface{}:
			if len(val) == 0 {
				delete(m, k)
			}
		default:
			if isZeroValue(v) {
				delete(m, k)
			}
		}
	}
}

package dsl

import (
	"fmt"

	"github.com/alecthomas/participle/v2/lexer"
)

// Position represents a source location.
type Position struct {
	Line   int
	Column int
}

func (p Position) String() string {
	return fmt.Sprintf("line %d, column %d", p.Line, p.Column)
}

// posFromLexer converts a participle lexer.Position to our Position.
func posFromLexer(p lexer.Position) Position {
	return Position{Line: p.Line, Column: p.Column}
}

// ---------- Participle Grammar AST (raw parse tree) ----------

// rawProgram is the root parse node.
type rawProgram struct {
	Pos     lexer.Position
	Entries []*rawTopLevel `parser:"@@*"`
}

// rawTopLevel is a union for top-level declarations.
type rawTopLevel struct {
	Pos          lexer.Position
	Routing      *rawRoutingDecl      `parser:"  @@"`
	Entrypoint   *rawEntrypointDecl   `parser:"| @@"`
	Recipe       *rawRecipeDecl       `parser:"| @@"`
	Signal       *rawSignalDecl       `parser:"| @@"`
	Projection   *rawProjectionDecl   `parser:"| @@"`
	Route        *rawRouteDecl        `parser:"| @@"`
	DecisionTree *rawDecisionTreeDecl `parser:"| @@"`
	Model        *rawModelDecl        `parser:"| @@"`
	Plugin       *rawPluginDecl       `parser:"| @@"`
	TestBlock    *rawTestBlockDecl    `parser:"| @@"`
}

// rawRoutingDecl configures the ordering strategy for the current routing
// scope. At the top level it describes the default profile; inside RECIPE it
// applies only to that recipe.
type rawRoutingDecl struct {
	Pos    lexer.Position
	Fields []*FieldEntry `parser:"'ROUTING' '{' @@* '}'"`
}

// rawEntrypointDecl binds one or more request-facing model IDs to a recipe.
type rawEntrypointDecl struct {
	Pos    lexer.Position
	Fields []*FieldEntry `parser:"'ENTRYPOINT' '{' @@* '}'"`
}

// rawRecipeDecl owns a complete, isolated routing program. MODEL declarations
// intentionally remain top-level because the runtime model catalog is shared.
type rawRecipeDecl struct {
	Pos  lexer.Position
	Name string            `parser:"'RECIPE' @(Ident | String)"`
	Opts []*RouteOpt       `parser:"( '(' @@* ')' )?"`
	Body []*rawRecipeEntry `parser:"'{' @@* '}'"`
}

type rawRecipeEntry struct {
	Pos          lexer.Position
	Routing      *rawRoutingDecl      `parser:"  @@"`
	Signal       *rawSignalDecl       `parser:"| @@"`
	Projection   *rawProjectionDecl   `parser:"| @@"`
	Route        *rawRouteDecl        `parser:"| @@"`
	DecisionTree *rawDecisionTreeDecl `parser:"| @@"`
	Plugin       *rawPluginDecl       `parser:"| @@"`
	TestBlock    *rawTestBlockDecl    `parser:"| @@"`
}

// rawTestBlockDecl: TEST <name> { entries... }
type rawTestBlockDecl struct {
	Pos     lexer.Position
	Name    string              `parser:"'TEST' @(Ident | String)"`
	Entries []*rawTestEntryDecl `parser:"'{' @@* '}'"`
}

// rawTestEntryDecl: "query" -> route_name
type rawTestEntryDecl struct {
	Pos       lexer.Position
	Query     string `parser:"@String"`
	RouteName string `parser:"Arrow @(Ident | String)"`
}

// rawSignalDecl: SIGNAL <type> <name> { fields... }
type rawSignalDecl struct {
	Pos        lexer.Position
	SignalType string        `parser:"'SIGNAL' @Ident"`
	Name       string        `parser:"@(Ident | String)"`
	Fields     []*FieldEntry `parser:"'{' @@* '}'"`
}

// rawProjectionDecl: PROJECTION <partition|score|mapping> <name> { fields... }
type rawProjectionDecl struct {
	Pos    lexer.Position
	Kind   string        `parser:"'PROJECTION' @('partition' | 'score' | 'mapping')"`
	Name   string        `parser:"@(Ident | String)"`
	Fields []*FieldEntry `parser:"'{' @@* '}'"`
}

// rawRouteDecl: ROUTE <name> (opts...) { body... }
type rawRouteDecl struct {
	Pos  lexer.Position
	Name string          `parser:"'ROUTE' @(Ident | String)"`
	Opts []*RouteOpt     `parser:"( '(' @@* ')' )?"`
	Body []*rawRouteItem `parser:"'{' @@* '}'"`
}

// rawDecisionTreeDecl: DECISION_TREE <name> { IF ... ELSE IF ... ELSE ... }
type rawDecisionTreeDecl struct {
	Pos     lexer.Position
	Name    string                     `parser:"'DECISION_TREE' @(Ident | String)"`
	If      *rawDecisionTreeIfBranch   `parser:"'{' @@"`
	ElseIfs []*rawDecisionTreeIfBranch `parser:"@@*"`
	Else    *rawDecisionTreeElseBranch `parser:"@@ '}'"`
}

// rawDecisionTreeIfBranch represents IF/ELSE IF branches inside DECISION_TREE.
type rawDecisionTreeIfBranch struct {
	Pos       lexer.Position
	Condition *BoolExprTop           `parser:"( 'IF' | 'ELSE' 'IF' ) @@"`
	Body      []*rawDecisionTreeItem `parser:"'{' @@* '}'"`
}

// rawDecisionTreeElseBranch represents the terminal ELSE branch.
type rawDecisionTreeElseBranch struct {
	Pos  lexer.Position
	Body []*rawDecisionTreeItem `parser:"'ELSE' '{' @@* '}'"`
}

// rawDecisionTreeItem is a route-like statement inside one DECISION_TREE branch.
type rawDecisionTreeItem struct {
	Pos          lexer.Position
	Name         *string              `parser:"  'NAME' @(Ident | String)"`
	Description  *string              `parser:"| 'DESCRIPTION' @String"`
	Tier         *int                 `parser:"| 'TIER' @Int"`
	Model        *rawModelList        `parser:"| 'MODEL' @@"`
	Algorithm    *rawAlgoSpec         `parser:"| 'ALGORITHM' @@"`
	Plugin       *rawPluginRef        `parser:"| 'PLUGIN' @@"`
	CandidateFor *rawCandidateForDecl `parser:"| @@"`
	Emit         *rawEmitDecl         `parser:"| @@"`
}

// rawEmitDecl: EMIT <kind> { fields... }. Currently only kind="retention" is
// recognized by the validator, but the grammar accepts any identifier so the
// validator can emit a friendly error rather than a parse error.
type rawEmitDecl struct {
	Pos    lexer.Position
	Kind   string        `parser:"'EMIT' @Ident"`
	Fields []*FieldEntry `parser:"'{' @@* '}'"`
}

// rawModelDecl: MODEL <name> { fields... }
type rawModelDecl struct {
	Pos    lexer.Position
	Name   string        `parser:"'MODEL' @(Ident | String)"`
	Fields []*FieldEntry `parser:"'{' @@* '}'"`
}

// RouteOpt: key = value inside route header parens
type RouteOpt struct {
	Pos   lexer.Position
	Key   string `parser:"@Ident '='"`
	Value *Val   `parser:"@@"`
}

// rawRouteItem: a single element inside a route body
type rawRouteItem struct {
	Pos          lexer.Position
	Priority     *int                 `parser:"  'PRIORITY' @Int"`
	Tier         *int                 `parser:"| 'TIER' @Int"`
	When         *BoolExprTop         `parser:"| 'WHEN' @@"`
	Model        *rawModelList        `parser:"| 'MODEL' @@"`
	Algorithm    *rawAlgoSpec         `parser:"| 'ALGORITHM' @@"`
	Plugin       *rawPluginRef        `parser:"| 'PLUGIN' @@"`
	Description  *string              `parser:"| 'DESCRIPTION' @String"`
	CandidateFor *rawCandidateForDecl `parser:"| @@"`
	Emit         *rawEmitDecl         `parser:"| @@"`
}

// rawCandidateForDecl: FOR <var> IN decision.candidates|[models...] { body... }
type rawCandidateForDecl struct {
	Pos    lexer.Position
	Var    string                       `parser:"'FOR' @Ident"`
	Source *rawCandidateIterationSource `parser:"'IN' @@"`
	Body   []*rawCandidateIterationItem `parser:"'{' @@* '}'"`
}

// rawCandidateIterationSource is either the current decision candidate set or
// an explicit bounded model list.
type rawCandidateIterationSource struct {
	Ref    *string       `parser:"  @(Ident | String)"`
	Models *rawModelList `parser:"| '[' @@ ']'"`
}

// rawCandidateIterationItem is a structured output inside a bounded candidate
// iteration block. The initial surface only feeds MODEL outputs back into the
// existing decision model-ref contract.
type rawCandidateIterationItem struct {
	Pos   lexer.Position
	Model *rawModelList `parser:"'MODEL' @@"`
}

// rawPluginDecl: PLUGIN <name> <type> { fields... }
type rawPluginDecl struct {
	Pos        lexer.Position
	Name       string        `parser:"'PLUGIN' @(Ident | String)"`
	PluginType string        `parser:"@Ident"`
	Fields     []*FieldEntry `parser:"'{' @@* '}'"`
}

// rawPluginRef: <name> { fields... }? inside a route
type rawPluginRef struct {
	Pos    lexer.Position
	Name   string        `parser:"@(Ident | String)"`
	Fields []*FieldEntry `parser:"( '{' @@* '}' )?"`
}

// rawModelList: comma-separated model refs (trailing comma tolerated)
type rawModelList struct {
	Pos    lexer.Position
	Models []*rawModelRef `parser:"@@ ( ',' @@ )* ','?"`
}

// rawModelRef: "model_name" or model_name (options...)?
type rawModelRef struct {
	Pos     lexer.Position
	Model   string      `parser:"@(String | Ident)"`
	Options []*ModelOpt `parser:"( '(' @@ ( ',' @@ )* ','? ')' )?"`
}

// ModelOpt: key = value inside model options
type ModelOpt struct {
	Key   string `parser:"@Ident '='"`
	Value *Val   `parser:"@@"`
}

// rawAlgoSpec: <type> { fields... }?
type rawAlgoSpec struct {
	Pos      lexer.Position
	AlgoType string        `parser:"@Ident"`
	Fields   []*FieldEntry `parser:"( '{' @@* '}' )?"`
}

// ---------- Boolean Expressions (parsed by participle) ----------

// BoolExprTop: OR-separated terms
type BoolExprTop struct {
	Pos   lexer.Position
	Terms []*BoolAndTerm `parser:"@@ ( 'OR' @@ )*"`
}

// BoolAndTerm: AND-separated factors
type BoolAndTerm struct {
	Pos     lexer.Position
	Factors []*BoolFactor `parser:"@@ ( 'AND' @@ )*"`
}

// BoolFactor: NOT, parenthesized expr, or signal ref
type BoolFactor struct {
	Pos       lexer.Position
	Not       *BoolFactor       `parser:"  'NOT' @@"`
	Paren     *BoolExprTop      `parser:"| '(' @@ ')'"`
	SignalRef *rawSignalRefExpr `parser:"| @@"`
}

// rawSignalRefExpr: signal_type("signal_name", optional: fields)
type rawSignalRefExpr struct {
	Pos        lexer.Position
	SignalType string        `parser:"@Ident"`
	SignalName string        `parser:"'(' @(String | Ident)"`
	Fields     []*FieldEntry `parser:"@@* ')'"`
}

// ---------- Field / Value (parsed by participle) ----------

// FieldEntry: key: value ,?
type FieldEntry struct {
	Pos   lexer.Position
	Key   string `parser:"','? @Ident ':'"`
	Value *Val   `parser:"@@"`
}

// Val: value union (string, int, float, bool, array, object, bare ident)
type Val struct {
	Pos      lexer.Position
	Str      *string       `parser:"  @String"`
	Float    *float64      `parser:"| @Float"`
	Int      *int          `parser:"| @Int"`
	Bool     *string       `parser:"| @('true' | 'false')"`
	ArrayVal *ArrayVal     `parser:"| @@"`
	Object   []*FieldEntry `parser:"| '{' @@* '}'"`
	BareStr  *string       `parser:"| @Ident"`
}

// ArrayVal wraps array parsing to handle empty arrays.
type ArrayVal struct {
	Pos   lexer.Position
	Items []*Val `parser:"'[' ( @@ ( ',' @@ )* ','? )? ']'"`
}

// ---------- Resolved AST (used by compiler/decompiler/validator) ----------

// Program is the root AST node, representing a complete DSL file.
type Program struct {
	Strategy             string
	Entrypoints          []*EntrypointDecl
	Recipes              []*RecipeDecl
	Signals              []*SignalDecl
	ProjectionPartitions []*ProjectionPartitionDecl
	ProjectionScores     []*ProjectionScoreDecl
	ProjectionMappings   []*ProjectionMappingDecl
	Routes               []*RouteDecl
	Models               []*ModelDecl
	Plugins              []*PluginDecl
	TestBlocks           []*TestBlockDecl
}

// EntrypointDecl is the DSL form of one request-facing recipe binding.
type EntrypointDecl struct {
	ModelNames []string
	Recipe     string
	Pos        Position
}

// RecipeDecl is an isolated routing scope. Program contains only recipe-local
// signals, projections, plugins, decisions, and tests; models are resolved
// from the parent Program.
type RecipeDecl struct {
	Name        string
	Description string
	Program     *Program
	Pos         Position
}

// ProjectionPartitionDecl declares a mutually exclusive partition of signals.
// When Semantics is "softmax_exclusive", the runtime applies Voronoi
// normalization so that at most one member fires per query.
type ProjectionPartitionDecl struct {
	Name        string
	Semantics   string
	Temperature float64
	Members     []string
	Default     string
	Pos         Position
}

// ProjectionScoreDecl defines a weighted derived score over base signals.
type ProjectionScoreDecl struct {
	Name   string
	Method string
	Inputs []*ProjectionScoreInputDecl
	Pos    Position
}

// ProjectionScoreInputDecl is one weighted contribution to a projection score.
type ProjectionScoreInputDecl struct {
	SignalType  string
	SignalName  string
	KB          string
	Metric      string
	Weight      float64
	ValueSource string
	Match       float64
	Miss        float64
}

// ProjectionMappingDecl maps one score into named routing outputs.
type ProjectionMappingDecl struct {
	Name        string
	Source      string
	Method      string
	Calibration *ProjectionMappingCalibrationDecl
	Outputs     []*ProjectionMappingOutputDecl
	Pos         Position
}

// ProjectionMappingCalibrationDecl controls confidence derived from the mapped band.
type ProjectionMappingCalibrationDecl struct {
	Method string
	Slope  float64
}

// ProjectionMappingOutputDecl defines one threshold band emitted by a mapping.
type ProjectionMappingOutputDecl struct {
	Name string
	LT   *float64
	LTE  *float64
	GT   *float64
	GTE  *float64
}

// TestBlockDecl declares expected routing outcomes for specific queries.
// Native validation paths can run them through the routing signal pipeline
// to catch conflicts that static checks cannot find.
type TestBlockDecl struct {
	Name    string
	Entries []*TestEntry
	Pos     Position
}

// TestEntry is a single query → expected route mapping inside a TEST block.
type TestEntry struct {
	Query     string
	RouteName string
	Pos       Position
}

// SignalDecl represents a SIGNAL declaration.
type SignalDecl struct {
	SignalType string
	Name       string
	Fields     map[string]Value
	Pos        Position
}

// RouteDecl represents a ROUTE declaration.
type RouteDecl struct {
	Name                string
	Description         string
	Priority            int
	Tier                int
	When                BoolExpr
	Models              []*ModelRef
	Algorithm           *AlgoSpec
	Plugins             []*PluginRef
	CandidateIterations []*CandidateIterationDecl
	Emits               []*EmitDecl
	Pos                 Position
}

// EmitDecl is the resolved AST node for an EMIT block. The Retention pointer
// is populated when Kind == "retention". Future Kind values (e.g. "log",
// "metric") will add their own typed payload fields here.
type EmitDecl struct {
	Kind      string
	Retention *RetentionDirective
	// RawFields preserves the parsed EMIT payload for validation. The typed
	// Retention field intentionally drops unknown or wrong-typed entries; the
	// validator/compiler still need the raw entries so authoring mistakes are
	// reported instead of being silently treated as an empty directive.
	RawFields []*FieldEntry
	Pos       Position
}

// RetentionDirective is the DSL-resolved form of an EMIT retention block.
// Pointer fields preserve tri-state semantics so we can tell "unset" apart
// from "explicitly false / 0".
type RetentionDirective struct {
	Drop                  *bool
	TTLTurns              *int
	KeepCurrentModel      *bool
	PreferPrefixRetention *bool
}

// CandidateIterationDecl represents a bounded FOR ... IN block over candidate
// models. Source is either "decision.candidates" or "models".
type CandidateIterationDecl struct {
	Variable string
	Source   string
	Models   []*ModelRef
	Outputs  []*CandidateIterationOutputDecl
	Pos      Position
}

// CandidateIterationOutputDecl describes how the iteration feeds an existing
// routing construct. The initial output type is "model" with Value equal to the
// iteration variable.
type CandidateIterationOutputDecl struct {
	Type   string
	Value  string
	Models []*ModelRef
	Pos    Position
}

// ModelDecl represents a top-level model catalog entry.
type ModelDecl struct {
	Name   string
	Fields map[string]Value
	Pos    Position
}

// PluginDecl represents a top-level PLUGIN template declaration.
type PluginDecl struct {
	Name       string
	PluginType string
	Fields     map[string]Value
	Pos        Position
}

// PluginRef represents a plugin reference inside a ROUTE.
type PluginRef struct {
	Name   string
	Fields map[string]Value
	Pos    Position
}

// ---------- Boolean Expressions (resolved) ----------

// BoolExpr is the interface for all boolean expression AST nodes.
type BoolExpr interface {
	boolExpr() // marker method
	GetPos() Position
}

// BoolAnd represents: <left> AND <right>
type BoolAnd struct {
	Left  BoolExpr
	Right BoolExpr
	Pos   Position
}

func (b *BoolAnd) boolExpr()        {}
func (b *BoolAnd) GetPos() Position { return b.Pos }

// BoolOr represents: <left> OR <right>
type BoolOr struct {
	Left  BoolExpr
	Right BoolExpr
	Pos   Position
}

func (b *BoolOr) boolExpr()        {}
func (b *BoolOr) GetPos() Position { return b.Pos }

// BoolNot represents: NOT <expr>
type BoolNot struct {
	Expr BoolExpr
	Pos  Position
}

func (b *BoolNot) boolExpr()        {}
func (b *BoolNot) GetPos() Position { return b.Pos }

// SignalRefExpr represents a signal reference in a boolean expression.
type SignalRefExpr struct {
	SignalType string
	SignalName string
	Fields     map[string]Value
	Pos        Position
}

func (s *SignalRefExpr) boolExpr()        {}
func (s *SignalRefExpr) GetPos() Position { return s.Pos }

// ---------- Model References ----------

// ModelRef represents a model reference in a ROUTE.
type ModelRef struct {
	Model     string
	Reasoning *bool
	Effort    string
	LoRA      string
	ParamSize string
	Weight    float64
	Pos       Position
}

// ---------- Algorithm Specification ----------

// AlgoSpec represents an ALGORITHM block in a ROUTE.
type AlgoSpec struct {
	AlgoType string
	Fields   map[string]Value
	Pos      Position
}

// ---------- Value Types ----------

// Value is the interface for all DSL value types.
type Value interface {
	value() // marker method
}

// StringValue represents a string literal.
type StringValue struct{ V string }

func (v StringValue) value() {}

// IntValue represents an integer literal.
type IntValue struct{ V int }

func (v IntValue) value() {}

// FloatValue represents a floating-point literal.
type FloatValue struct{ V float64 }

func (v FloatValue) value() {}

// BoolValue represents a boolean literal.
type BoolValue struct{ V bool }

func (v BoolValue) value() {}

// ArrayValue represents an array: [v1, v2, ...]
type ArrayValue struct{ Items []Value }

func (v ArrayValue) value() {}

// ObjectValue represents a nested object: { key: value, ... }
type ObjectValue struct{ Fields map[string]Value }

func (v ObjectValue) value() {}

