1	package dsl
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7	
8		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
9	)
10	
11	func (d *decompiler) decompileCandidateIteration(iter config.CandidateIterationConfig) {
12		source := iter.Source
13		if source == "models" {
14			source = decompileCandidateIterationModelSource(iter.Models)
15		}
16		d.write("  FOR %s IN %s {\n", sanitizeName(iter.Variable), source)
17		for _, output := range iter.Outputs {
18			if output.Type == "model" {
19				d.write("    MODEL %s\n", sanitizeName(output.Value))
20			}
21		}
22		d.write("  }\n")
23	}
24	
25	func decompileCandidateIterationModelSource(models []config.ModelRef) string {
26		if len(models) == 0 {
27			return "[]"
28		}
29		var sb strings.Builder
30		sb.WriteString("[")
31		for i, model := range models {
32			if i > 0 {
33				sb.WriteString(", ")
34			}
35			sb.WriteString(strconv.Quote(model.Model))
36			opts := candidateIterationModelRefOptions(&model)
37			if opts != "" {
38				sb.WriteString(" (")
39				sb.WriteString(opts)
40				sb.WriteString(")")
41			}
42		}
43		sb.WriteString("]")
44		return sb.String()
45	}
46	
47	func candidateIterationModelRefOptions(model *config.ModelRef) string {
48		var opts []string
49		if model.UseReasoning != nil {
50			opts = append(opts, fmt.Sprintf("reasoning = %t", *model.UseReasoning))
51		}
52		if model.ReasoningEffort != "" {
53			opts = append(opts, fmt.Sprintf("effort = %q", model.ReasoningEffort))
54		}
55		if model.LoRAName != "" {
56			opts = append(opts, fmt.Sprintf("lora = %q", model.LoRAName))
57		}
58		if model.Weight != 0 {
59			opts = append(opts, fmt.Sprintf("weight = %s", strconv.FormatFloat(model.Weight, 'f', -1, 64)))
60		}
61		return strings.Join(opts, ", ")
62	}
63	
64	func candidateIterationsCoverModelRefs(dec config.Decision) bool {
65		// The MODEL omission optimization is only proven for one explicit-model
66		// iteration that emits MODEL <iterator>. Multiple iterations require a
67		// merge/order/dedup contract before they can safely cover ModelRefs.
68		if len(dec.CandidateIterations) != 1 {
69			return false
70		}
71		iter := dec.CandidateIterations[0]
72		if iter.Source != "models" || !iterEmitsVariable(iter) {
73			return false
74		}
75		if len(dec.ModelRefs) != len(iter.Models) {
76			return false
77		}
78		for i := range dec.ModelRefs {
79			if dec.ModelRefs[i].Model != iter.Models[i].Model ||
80				dec.ModelRefs[i].LoRAName != iter.Models[i].LoRAName {
81				return false
82			}
83		}
84		return true
85	}
86	
87	func decompileRuleNode(node *config.RuleCombination) string {
88		if node == nil {
89			return ""
90		}
91	
92		// Leaf node — signal reference
93		if node.Type != "" {
94			return decompileRuleLeaf(node)
95		}
96	
97		switch node.Operator {
98		case "AND":
99			// Flatten nested ANDs into a flat list: a AND b AND c
100			parts := flattenRuleNode(node, "AND")
101			return strings.Join(parts, " AND ")
102		case "OR":
103			// Flatten nested ORs into a flat list: (a OR b OR c)
104			parts := flattenRuleNode(node, "OR")
105			if len(parts) == 1 {
106				return parts[0]
107			}
108			return "(" + strings.Join(parts, " OR ") + ")"
109		case "NOT":
110			if len(node.Conditions) == 1 {
111				inner := decompileRuleNode(&node.Conditions[0])
112				return "NOT " + inner
113			}
114		}
115	
116		return decompileRuleFallback(node)
117	}
118	
119	func decompileRuleLeaf(node *config.RuleCombination) string {
120		arguments := []string{fmt.Sprintf("%q", node.Name)}
121		if node.Label != "" {
122			arguments = append(arguments, fmt.Sprintf("label: %q", node.Label))
123		}
124		if node.Predicate != nil {
125			arguments = append(
126				arguments,
127				"predicate: "+formatPluginConfigValue(
128					structurePredicateToMap(node.Predicate),
129				),
130			)
131		}
132		if node.OnError != "" {
133			arguments = append(arguments, fmt.Sprintf("on_error: %q", node.OnError))
134		}
135		return fmt.Sprintf("%s(%s)", node.Type, strings.Join(arguments, ", "))
136	}
137	
138	func decompileRuleFallback(node *config.RuleCombination) string {
139		parts := make([]string, 0, len(node.Conditions))
140		for _, c := range node.Conditions {
141			parts = append(parts, decompileRuleNode(&c))
142		}
143		if node.Operator != "" {
144			return strings.Join(parts, " "+node.Operator+" ")
145		}
146		return strings.Join(parts, " AND ")
147	}
148	
149	func flattenRuleNode(node *config.RuleCombination, op string) []string {
150		if node.Operator == op {
151			var parts []string
152			for i := range node.Conditions {
153				parts = append(parts, flattenRuleNode(&node.Conditions[i], op)...)
154			}
155			return parts
156		}
157		return []string{decompileRuleNode(node)}
158	}
159	
160	func (d *decompiler) decompileAlgorithmFields(algo *config.AlgorithmConfig) string {
161		if algo == nil {
162			return ""
163		}
164		fields := d.algorithmToFields(algo)
165		if len(fields) == 0 {
166			return ""
167		}
168	
169		var sb strings.Builder
170		for _, key := range sortedKeys(fields) {
171			fmt.Fprintf(&sb, "    %s: %s\n", key, formatDSLFieldValue(fields[key]))
172		}
173		return sb.String()
174	}
175	
176	func formatDSLFieldValue(value Value) string {
177		return formatPluginConfigValue(dslFieldValueFromValue(value).asInterface())
178	}
179	
180	func decompileComposerObj(node *config.RuleCombination) string {
181		if node == nil {
182			return "{}"
183		}
184		if node.Type != "" {
185			return fmt.Sprintf("{ type: %q, name: %q }", node.Type, node.Name)
186		}
187		var parts []string
188		for i := range node.Conditions {
189			parts = append(parts, decompileComposerObj(&node.Conditions[i]))
190		}
191		return fmt.Sprintf("{ operator: %q, conditions: [%s] }", node.Operator, strings.Join(parts, ", "))
192	}
193	
194	func (d *decompiler) decompileDecisions() {
195		for _, dec := range d.cfg.Decisions {
196			d.decompileDecision(dec)
197		}
198	}
199	
200	func (d *decompiler) decompileDecision(dec config.Decision) {
201		d.writeDecisionHeader(dec)
202		d.write("  PRIORITY %d\n", dec.Priority)
203		if dec.Tier != 0 {
204			d.write("  TIER %d\n", dec.Tier)
205		}
206		if ruleExpr := decompileRuleNode(&dec.Rules); ruleExpr != "" {
207			d.write("  WHEN %s\n", ruleExpr)
208		}
209		d.writeDecisionModels(dec)
210		for _, iter := range dec.CandidateIterations {
211			d.decompileCandidateIteration(iter)
212		}
213		d.writeDecisionAlgorithm(dec)
214		d.writeDecisionPlugins(dec)
215		for _, e := range dec.Emits {
216			d.decompileEmit(e)
217		}
218		d.write("}\n\n")
219	}
220	
221	func (d *decompiler) writeDecisionHeader(dec config.Decision) {
222		if dec.Description != "" {
223			d.write("ROUTE %s (description = %q) {\n", quoteName(dec.Name), dec.Description)
224			return
225		}
