1	package dsl
2	
3	import (
4		"fmt"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
7	)
8	
9	// compileScopes lowers recipe-local programs after the shared model catalog
10	// and default routing profile have been compiled. Every recipe receives a new
11	// Compiler instance, which makes accidental cross-recipe symbol reuse
12	// structurally impossible.
13	func (c *Compiler) compileScopes() {
14		if err := c.config.Strategy.Validate(); err != nil {
15			c.errors = append(c.errors, err)
16		}
17		recipeNames := c.compileRecipes()
18		c.compileEntrypoints(recipeNames)
19	}
20	
21	func (c *Compiler) compileRecipes() map[config.RecipeName]struct{} {
22		c.config.Recipes = []config.RoutingRecipe{{
23			Name: config.DefaultRecipeName,
24			Profile: config.RoutingProfile{
25				Signals:     c.config.Signals,
26				Projections: c.config.Projections,
27				Decisions:   c.config.Decisions,
28				Strategy:    c.config.Strategy,
29			},
30		}}
31	
32		recipeNames := map[config.RecipeName]struct{}{config.DefaultRecipeName: {}}
33		for _, recipe := range c.prog.Recipes {
34			name := config.RecipeName(recipe.Name)
35			if name == "" {
36				c.addError(recipe.Pos, "RECIPE name cannot be empty")
37				continue
38			}
39			if _, exists := recipeNames[name]; exists {
40				c.addError(recipe.Pos, "duplicate RECIPE %q", name)
41				continue
42			}
43			recipeNames[name] = struct{}{}
44	
45			child := newScopedCompiler(recipe.Program)
46			child.compile()
47			if err := child.config.Strategy.Validate(); err != nil {
48				child.errors = append(child.errors, err)
49			}
50			for _, err := range child.errors {
51				c.errors = append(c.errors, fmt.Errorf("RECIPE %q: %w", name, err))
52			}
53			c.config.Recipes = append(c.config.Recipes, config.RoutingRecipe{
54				Name:        name,
55				Description: recipe.Description,
56				Profile: config.RoutingProfile{
57					Signals:     child.config.Signals,
58					Projections: child.config.Projections,
59					Decisions:   child.config.Decisions,
60					Strategy:    child.config.Strategy,
61				},
62			})
63		}
64		return recipeNames
65	}
66	
67	func (c *Compiler) compileEntrypoints(recipeNames map[config.RecipeName]struct{}) {
68		seenModels := make(map[string]struct{})
69		for _, entrypoint := range c.prog.Entrypoints {
70			recipeName := config.RecipeName(entrypoint.Recipe)
71			if _, exists := recipeNames[recipeName]; !exists {
72				c.addError(entrypoint.Pos, "ENTRYPOINT references unknown recipe %q", entrypoint.Recipe)
73				continue
74			}
75			for _, modelName := range entrypoint.ModelNames {
76				if modelName == "" {
77					c.addError(entrypoint.Pos, "ENTRYPOINT model_names cannot contain an empty value")
78					continue
79				}
80				if _, exists := seenModels[modelName]; exists {
81					c.addError(entrypoint.Pos, "entrypoint model %q is mapped more than once", modelName)
82					continue
83				}
84				seenModels[modelName] = struct{}{}
85			}
86			c.config.Entrypoints = append(c.config.Entrypoints, config.EntrypointMapping{
87				ModelNames: append([]string(nil), entrypoint.ModelNames...),
88				Recipe:     recipeName,
89			})
90		}
91	}
92	
93	func newScopedCompiler(prog *Program) *Compiler {
94		defaults := config.DefaultGlobalConfig()
95		c := &Compiler{
96			prog: prog,
97			config: &config.RouterConfig{
98				IntelligentRouting: config.IntelligentRouting{
99					ModelSelection: defaults.ModelSelection,
100				},
101			},
102			pluginTemplates: make(map[string]*PluginDecl),
103		}
104		c.config.Strategy = config.RoutingStrategy(prog.Strategy)
105		return c
106	}
