383	func parseAuthzSubjects(v Value) []config.Subject {
384		arr, ok := v.(ArrayValue)
385		if !ok {
386			return nil
387		}
388		subjects := make([]config.Subject, 0, len(arr.Items))
389		for _, item := range arr.Items {
390			obj, ok := item.(ObjectValue)
391			if !ok {
392				continue
393			}
394			subj := config.Subject{}
395			if kind, ok := getStringField(obj.Fields, "kind"); ok {
396				subj.Kind = kind
397			}
398			if name, ok := getStringField(obj.Fields, "name"); ok {
399				subj.Name = name
400			}
401			subjects = append(subjects, subj)
402		}
403		return subjects
404	}
