373	func ruleTreeContainsNegatedSignal(node *config.RuleCombination, signalType string, name string) bool {
374		return ruleTreeContainsSignal(node, false, signalType, name)
375	}
376	
377	func ruleTreeContainsSignal(node *config.RuleCombination, negated bool, signalType string, name string) bool {
378		if node == nil {
379			return false
380		}
381		if node.Type != "" {
382			return negated && node.Type == signalType && node.Name == name
383		}
384	
385		childNegated := negated
386		if node.Operator == "NOT" {
387			childNegated = !negated
388		}
389		for i := range node.Conditions {
390			if ruleTreeContainsSignal(&node.Conditions[i], childNegated, signalType, name) {
391				return true
392			}
393		}
394		return false
395	}
