288		if model.ParamSize != "" {
289			fields["param_size"] = StringValue{V: model.ParamSize}
290		}
291		if model.ContextWindowSize > 0 {
292			fields["context_window_size"] = IntValue{V: model.ContextWindowSize}
293		}
294		if model.Description != "" {
295			fields["description"] = StringValue{V: model.Description}
296		}
297		if len(model.Capabilities) > 0 {
298			fields["capabilities"] = stringsToArray(model.Capabilities)
299		}
300		if len(model.LoRAs) > 0 {
301			items := make([]Value, 0, len(model.LoRAs))
302			for _, adapter := range model.LoRAs {
303				loraFields := map[string]Value{
304					"name": StringValue{V: adapter.Name},
305				}
306				if adapter.Description != "" {
307					loraFields["description"] = StringValue{V: adapter.Description}
308				}
309				items = append(items, ObjectValue{Fields: loraFields})
310			}
311			fields["loras"] = ArrayValue{Items: items}
312		}
313		if len(model.Tags) > 0 {
314			fields["tags"] = stringsToArray(model.Tags)
315		}
316		if model.QualityScore != 0 {
317			fields["quality_score"] = FloatValue{V: model.QualityScore}
318		}
319		if model.Modality != "" {
320			fields["modality"] = StringValue{V: model.Modality}
321		}
322		return &ModelDecl{Name: model.Name, Fields: fields}
323	}
324	
325	func quotedStringArray(values []string) string {
326		if len(values) == 0 {
327			return "[]"
328		}
329		quoted := make([]string, 0, len(values))
330		for _, value := range values {
331			quoted = append(quoted, strconv.Quote(value))
332		}
333		return "[" + strings.Join(quoted, ", ") + "]"
334	}
